import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';

const CartComponent = () => {
  const cart = useSelector((state) => state.cart);
  const dispatch = useDispatch();

  const handleQuantityChange = (id, quantity) => {
    dispatch(addItem({ id, quantity }));
  }

  return (
    <div>
      {/* display cart info */}
      <h1>Cart</h1>
      <ul>
        {cart.items.map(item => {
          return (
            <li key={item.id}>
              <button onClick={() => dispatch(removeItem(item.id))}>
                <i className="fa fa-minus-circle" /> Remove
              </button>
              <div>
                Quantity:
                <input
                  type="number"
                  value={item.quantity}
                  onChange={e => handleQuantityChange(item.id, e.target.value)}
                />
              </div>
              <p>
                  <strong>${item.price}</strong> x quantity
                </p>
            </li>
          );
        })}
      </ul>
    </div>
  );
};
```

This is key, as it's all you need to persist cart state from the client-side to the reducer, which manages cart state. Next step: build out server-side rendering.

Here's the CartComponent. This one assumes you've got a Shop component like the one above already rendering your products; the `onAdd` function can be passed as an event handler for button clicks on products.

```jsx
import React from'react';
import { shallowEqual, useSelector, useDispatch } from'react-redux';
import { removeItem, addItem } from './cartSlice';

const CartComponent = () => {
  const dispatch = useDispatch();
  const items = useSelector(state => state.cart.items);
  const onAdd = item => dispatch(addItem(item));
  const onRemove = item => dispatch(removeItem(item.id));

  return (
    <div>
      <h2>Items: {items.length}</h2>
      <ol>
        {items.map(i => (
          <li key={i.id}>
            <span>{i.name}</span>
            <button onClick={() => onRemove(i)}>Remove</button>
          </li>
        ))}
      </ol>
      <button onClick={() => alert('Checkout!')}>Checkout</button>
    </div>
  );
};
```

